// ── Tournament player stats from scored matches (embedded in n8n; also unit-tested in node) ──
// matches: [{ division_id, innings: [{ batting_entry_id, bowling_entry_id, batting: [card], bowling: [card] }] }]
// Batting card: {id, name, runs, balls, fours, sixes, out}. Bowling card: {id, name, legal_balls, runs, wickets, maidens, dots}.
function computeStats(matches) {
  const players = new Map(); // `${division}:${memberId}` → totals
  const get = (div, id, name, entry) => {
    const k = `${div}:${id}`;
    if (!players.has(k)) players.set(k, { division_id: div, member_id: id, name, entry_id: entry, matches: new Set(),
      innings: 0, runs: 0, balls: 0, fours: 0, sixes: 0, outs: 0, high: 0, high_not_out: false, fifties: 0,
      bowl_innings: 0, legal_balls: 0, runs_conceded: 0, wickets: 0, maidens: 0, dots: 0, best_w: -1, best_r: 0 });
    return players.get(k);
  };
  matches.forEach((m, mi) => {
    for (const inn of m.innings || []) {
      for (const b of inn.batting || []) {
        const p = get(m.division_id, b.id, b.name, inn.batting_entry_id);
        p.matches.add(mi);
        p.innings++; p.runs += b.runs; p.balls += b.balls; p.fours += b.fours; p.sixes += b.sixes;
        if (b.out) p.outs++;
        if (b.runs > p.high || (b.runs === p.high && !b.out)) { p.high = b.runs; p.high_not_out = !b.out; }
        if (b.runs >= 50) p.fifties++;
      }
      for (const b of inn.bowling || []) {
        const p = get(m.division_id, b.id, b.name, inn.bowling_entry_id);
        p.matches.add(mi);
        p.bowl_innings++; p.legal_balls += b.legal_balls; p.runs_conceded += b.runs; p.wickets += b.wickets;
        p.maidens += b.maidens || 0; p.dots += b.dots || 0;
        if (b.wickets > p.best_w || (b.wickets === p.best_w && b.runs < p.best_r)) { p.best_w = b.wickets; p.best_r = b.runs; }
      }
    }
  });
  const r2 = v => Math.round(v * 100) / 100;
  return [...players.values()].map(p => ({
    division_id: p.division_id, member_id: p.member_id, name: p.name, entry_id: p.entry_id, matches: p.matches.size,
    innings: p.innings, runs: p.runs, balls: p.balls, fours: p.fours, sixes: p.sixes, outs: p.outs,
    highest: p.innings ? `${p.high}${p.high_not_out ? '*' : ''}` : null, highest_runs: p.high, fifties: p.fifties,
    average: p.outs ? r2(p.runs / p.outs) : null, strike_rate: p.balls ? r2(p.runs * 100 / p.balls) : null,
    overs: `${Math.floor(p.legal_balls / 6)}.${p.legal_balls % 6}`, legal_balls: p.legal_balls, runs_conceded: p.runs_conceded,
    wickets: p.wickets, maidens: p.maidens, dots: p.dots, economy: p.legal_balls ? r2(p.runs_conceded * 6 / p.legal_balls) : null,
    best: p.best_w >= 0 ? `${p.best_w}/${p.best_r}` : null, best_wickets: Math.max(0, p.best_w), best_runs: p.best_r,
  }));
}

/** Top players per category for one division. */
function leaderboards(rows, top = 10) {
  const take = (filter, sort) => rows.filter(filter).sort(sort).slice(0, top);
  return {
    most_runs: take(p => p.runs > 0, (a, b) => b.runs - a.runs || (b.strike_rate || 0) - (a.strike_rate || 0)),
    most_wickets: take(p => p.wickets > 0, (a, b) => b.wickets - a.wickets || (a.economy ?? 99) - (b.economy ?? 99)),
    highest_score: take(p => p.innings > 0 && p.highest_runs > 0, (a, b) => b.highest_runs - a.highest_runs),
    best_bowling: take(p => p.best_wickets > 0, (a, b) => b.best_wickets - a.best_wickets || a.best_runs - b.best_runs),
    most_sixes: take(p => p.sixes > 0, (a, b) => b.sixes - a.sixes),
    best_strike_rate: take(p => p.balls >= 10, (a, b) => b.strike_rate - a.strike_rate),
    best_economy: take(p => p.legal_balls >= 12, (a, b) => a.economy - b.economy),
  };
}


